def evict(cache, meta):
    t = meta["time"]
    recent = meta["recent"]
    freq = meta["cache_freq"]
    capacity = meta["capacity"]

    # Defensive (should not occur per spec)
    if len(cache) == 0:
        return 0

    # Build key→positions (0 = most recent in recent, increasing backward in time)
    key_positions = {}
    for i, key in enumerate(recent):
        if key not in key_positions:
            key_positions[key] = [i]
        elif len(key_positions[key]) < 4:  # keep up to 4 recurrences for stability
            key_positions[key].append(i)

    # Helper: compute periodic stability (1.0 = very stable, decays with noise/count)
    def stability_score(key):
        pos = key_positions.get(key, [])
        n = len(pos)
        if n < 2:
            return 0.1 * n  # weak but non-zero for 1-time keys

        # Compute gaps: pos[i] - pos[i+1] (should be positive for valid recurrences)
        gaps = [pos[i] - pos[i+1] for i in range(n-1)]
        if any(g <= 0 for g in gaps):
            return 0.1  # invalid pattern

        mean_gap = sum(gaps) / n
        if mean_gap < 1.5:  # too dense (e.g., burst), low stability
            return 0.2

        # Coefficient of variation
        var = sum((g - mean_gap) ** 2 for g in gaps) / (n - 1)
        cv = (var ** 0.5) / mean_gap if mean_gap > 0 else float('inf')

        # Stability: high if CV < 0.3, decays with CV and low recurrence count
        base = max(0.0, 1.0 - 2.0 * cv)
        return base * (0.5 + 0.5 * min(1.0, n / 3.0))

    # Detect recent sequential scan: check if last 8 keys are strictly decreasing by ~1
    scan_score = 0.0
    if len(recent) >= 8:
        last8 = recent[-8:]
        # Check if indices form a decreasing sequence (e.g., [20,19,18,17,...])
        # But keys aren't indices — so check *recency gaps* between consecutive accesses
        # Instead: compute gaps between last 4 accesses (in terms of positions in recent)
        recent_positions = {}
        for i in range(len(recent)):
            k = recent[i]
            if k not in recent_positions:
                recent_positions[k] = i
        # Look at the 4 most recent *distinct* keys and their positions
        seen = set()
        pos_list = []
        for i in reversed(range(len(recent))):
            k = recent[i]
            if k not in seen:
                seen.add(k)
                pos_list.append(i)
                if len(pos_list) == 4:
                    break
        if len(pos_list) == 4:
            gaps = [pos_list[i] - pos_list[i+1] for i in range(3)]
            if all(0 < g < 3 for g in gaps):  # gaps ~1 means recent & sequential
                scan_score = 1.0
            elif all(1 <= g <= 5 for g in gaps):
                scan_score = 0.5

    scores = {}
    for idx, key in enumerate(cache):
        f = freq.get(key, 0)
        # Frequency score (saturate at 20 to avoid burst noise)
        freq_score = min(1.0, f / 20.0)
        # Stability score
        stab = stability_score(key)
        # Hybrid score: freq × stability
        score = freq_score * stab

        # Cold key fallback: if no recurrence and freq=1, treat as LFU (lower is evict first)
        if f == 1 and stab < 0.2:
            score = 1e-6 * (1.0 + f / 5.0)
        elif f <= 1 and stab < 0.1:
            score = 1e-7  # very low

        # Scan protection: if in scan mode, protect most recently accessed item strongly
        if scan_score > 0.3:
            if recent and recent[-1] == key and idx == cache.index(key):
                # Override: protect the current most recent key in cache (if present)
                score = 1.5  # higher = *less* likely to evict (we minimize score later)
            elif recent and recent[-1] == key and key in cache:
                # Double-check index (cache.index is O(n), but n=50 is fine)
                # Already covered above, but safe
                pass

        scores[idx] = score

    # Evict the *lowest* score (least valuable)
    # Tie-break: prefer higher index (more recent in insertion order) to evict older items
    # But if scores equal, evict the one inserted earliest (lowest index) to keep cache newer
    return min(scores, key=lambda i: (scores[i], i))
